<script setup lang="ts">
import { reactive,ref } from 'vue'
import { ElMessage } from 'element-plus'
import { orderServiceApi } from '@/api/orderService'
const form=reactive<any>({serviceId:null,action:'renew',days:30,reason:''}),result=ref<any>(null),loading=ref(false),data=(r:any)=>r.data.data
async function submit(){if(!form.serviceId||!form.reason.trim()){ElMessage.warning('请填写服务ID和操作原因');return}loading.value=true;try{if(form.action==='renew')result.value=data(await orderServiceApi.renew(form.serviceId,form.days,form.reason));if(form.action==='suspend'){await orderServiceApi.suspend(form.serviceId,form.reason);result.value={status:'SUSPENDED'}}if(form.action==='resume'){await orderServiceApi.resume(form.serviceId,form.reason);result.value={status:'ACTIVE'}}if(form.action==='terminate')result.value=data(await orderServiceApi.terminate(form.serviceId,form.reason));ElMessage.success('服务变更完成')}finally{loading.value=false}}
</script><template><div class="page"><div><h2>服务变更</h2><p>集中执行续费、暂停、恢复和终止等服务生命周期操作。</p></div><el-card shadow="never" v-loading="loading"><el-form label-width="110px" style="max-width:650px"><el-form-item label="服务ID" required><el-input-number v-model="form.serviceId" :min="1"/></el-form-item><el-form-item label="变更类型"><el-select v-model="form.action"><el-option label="续费" value="renew"/><el-option label="暂停" value="suspend"/><el-option label="恢复" value="resume"/><el-option label="终止" value="terminate"/></el-select></el-form-item><el-form-item v-if="form.action==='renew'" label="续费天数"><el-input-number v-model="form.days" :min="1"/></el-form-item><el-form-item label="原因" required><el-input v-model="form.reason" type="textarea"/></el-form-item><el-form-item><el-button type="primary" @click="submit">执行变更</el-button></el-form-item></el-form></el-card><el-alert v-if="result" type="success" :closable="false" :title="`执行结果：${JSON.stringify(result)}`"/></div></template><style scoped>.page{display:grid;gap:16px}h2{margin:0 0 6px}p{margin:0;color:#7b8494}</style>